import validatorForm from "./components/checkRulesManageComponent/validatorForm";
import { validatorSearch, validatorDel } from "@/api/system/checkRulesManage";
export default {
  components: {
    validatorForm: validatorForm
  },
  data: function data() {
    return {
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      itemId: ''
    };
  },
  mounted: function mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
    this.getList();
  },
  methods: {
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = bodyBox[0].offsetHeight + 'px';
    },
    getList: function getList() {
      var _this = this;
      this.tableLoading = true;
      validatorSearch().then(function (res) {
        _this.tableData = res.Return.tbodyList;
        _this.tableLoading = false;
      }).catch(function () {
        _this.tableLoading = false;
      });
    },
    // 删除
    delItem: function delItem(row) {
      var _this2 = this;
      this.$confirm('确定删除该全局属性?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        validatorDel({
          id: row.id
        }).then(function (res) {
          _this2.$message({
            type: 'success',
            message: '删除成功！'
          });
          _this2.getList();
        });
      });
    },
    // 编辑
    editItem: function editItem(row) {
      this.showType = '修改';
      this.itemId = row.id;
      this.showForm = true;
    },
    saveValidator: function saveValidator() {
      this.showForm = false;
      this.getList();
    }
  }
};
